(function(root){
'use strict';
// 필기 연습: quiz over the written-exam textbooks (simulator/written-questions.js, generated by tools/build-written-questions.py).
// Not part of the real MMI; wrong answers are kept in this browser (localStorage) so they can be retried.
const doc=document,$=id=>doc.getElementById(id),KEY='orpheia.written';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bank=()=>root.SimWrittenQuestions||[];
const norm=s=>String(s??'').replace(/[\s,.·]/g,'').toLowerCase();
let queue=[],pos=0,score={right:0,wrong:0},answered=false;
function load(){try{return JSON.parse(localStorage.getItem(KEY))||{wrong:[]};}catch(e){return {wrong:[]};}}
function save(d){try{localStorage.setItem(KEY,JSON.stringify(d));}catch(e){}}
function wrongIds(){return load().wrong;}
function mark(id,ok){const d=load(),has=d.wrong.includes(id);if(!ok&&!has)d.wrong.push(id);if(ok&&has)d.wrong=d.wrong.filter(x=>x!==id);save(d);}
function shuffle(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function pool(){
 const src=$('wrSource').value,ch=$('wrChapter').value,scope=$('wrScope').value;
 let list=bank().filter(q=>(!src||q.source===src)&&(!ch||q.chapter===ch));
 if(scope==='wrong')list=list.filter(q=>wrongIds().includes(q.id));
 return list;
}
function chapters(){
 const src=$('wrSource').value,set=[...new Set(bank().filter(q=>!src||q.source===src).map(q=>q.chapter))];
 $('wrChapter').innerHTML='<option value="">전체 단원</option>'+set.map(c=>`<option>${esc(c)}</option>`).join('');
 count();
}
function count(){$('wrCount').textContent=`출제 대상 ${pool().length}문항 · 오답노트 ${wrongIds().length}문항`;}
function start(){
 let list=pool();if(!list.length){$('wrBody').innerHTML='<div class="trc-msg">조건에 맞는 문제가 없습니다.</div>';$('wrStatus').textContent='';return;}
 if($('wrShuffle').checked)list=shuffle(list);
 const n=Math.max(1,Math.min(list.length,parseInt($('wrNum').value,10)||list.length));
 queue=list.slice(0,n);pos=0;score={right:0,wrong:0};show();
}
function show(){
 if(pos>=queue.length)return finish();
 const q=queue[pos];answered=false;
 $('wrStatus').textContent=`${pos+1} / ${queue.length} · 정답 ${score.right} · 오답 ${score.wrong}`;
 const input=q.choices.length?`<div class="wr-choices">${q.choices.map((c,i)=>`<label><input type="radio" name="wrAns" value="${i+1}"> <span>${i+1}) ${esc(c)}</span></label>`).join('')}</div>`:'<input type="text" id="wrText" class="wr-text" placeholder="답을 입력하세요" autocomplete="off">';
 $('wrBody').innerHTML=`<div class="wr-meta">${esc(q.source)} · ${esc(q.chapter)} · ${q.no}번</div><div class="wr-q">${esc(q.q)}</div>${input}<div id="wrResult" class="trc-msg" role="status" hidden></div>`;
 $('wrSubmit').hidden=false;$('wrNext').hidden=true;
}
function check(q){
 if(q.choices.length){const v=doc.querySelector('input[name="wrAns"]:checked');return v?parseInt(v.value,10)===q.answer:null;}
 const v=norm($('wrText').value);return v?v===norm(q.text):null;
}
function submit(){
 if(answered||pos>=queue.length)return;
 const q=queue[pos],ok=check(q);
 if(ok===null){const r=$('wrResult');r.hidden=false;r.textContent='답을 선택(입력)한 뒤 제출하세요.';return;}
 answered=true;ok?score.right++:score.wrong++;mark(q.id,ok);
 const correct=q.choices.length?`${q.answer}) ${q.choices[q.answer-1]}`:q.text;
 const r=$('wrResult');r.hidden=false;r.className='trc-msg '+(ok?'ok':'bad');
 r.innerHTML=`<b>${ok?'정답입니다.':'오답입니다.'}</b> 정답: ${esc(correct)}${q.why?`<br>해설: ${esc(q.why)}`:''}${q.ref?`<br>근거: ${esc(q.ref)}`:''}${q.choices.length?'':'<br><small>단답형은 교재 표기와 글자가 같아야 정답으로 처리합니다.</small>'}`;
 $('wrSubmit').hidden=true;$('wrNext').hidden=false;
 $('wrStatus').textContent=`${pos+1} / ${queue.length} · 정답 ${score.right} · 오답 ${score.wrong}`;count();
}
function next(){pos++;show();}
function finish(){
 const total=score.right+score.wrong,pct=total?Math.round(score.right/total*100):0;
 $('wrBody').innerHTML=`<div class="wr-summary"><b>결과: ${score.right} / ${total} (${pct}점)</b><br>${pct>=60?'합격선(60점)을 넘었습니다.':'60점 미만입니다. 오답노트로 다시 풀어 보세요.'}<br>※ 60점은 이 시뮬레이터의 연습용 기준이며 실제 시험 기준이 아닙니다.</div>`;
 $('wrSubmit').hidden=true;$('wrNext').hidden=true;$('wrStatus').textContent='연습 종료';count();
}
function init(){
 const m=root.SimMMI,sources=[...new Set(bank().map(q=>q.source))];
 const win=m.createWindow('written',{title:'필기 연습 (교육용)',x:160,y:60,width:640,body:`<div class="rpt written"><div class="wr-opts"><label>교재 <select id="wrSource"><option value="">전체</option>${sources.map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><label>단원 <select id="wrChapter"></select></label><label>범위 <select id="wrScope"><option value="all">전체 문제</option><option value="wrong">오답노트</option></select></label><label>문항 수 <input type="number" id="wrNum" min="1" max="200" value="10"></label><label><input type="checkbox" id="wrShuffle" checked> 섞기</label></div><div class="idm-note" id="wrCount"></div><div id="wrStatus" class="wr-status"></div><div id="wrBody" class="wr-body"><div class="trc-msg">[시작]을 누르세요. 문제는 필기 교재의 단원 평가·종합 평가에서 가져왔습니다.</div></div><div class="idm-buttons"><button type="button" class="sched-btn primary" id="wrStart">시작</button><button type="button" class="sched-btn primary" id="wrSubmit" hidden>제출</button><button type="button" class="sched-btn" id="wrNext" hidden>다음 문제</button><button type="button" class="sched-btn" id="wrClear">오답노트 비우기</button><button type="button" class="sched-btn" id="wrClose">닫기</button></div></div>`});
 $('wrSource').onchange=chapters;$('wrChapter').onchange=count;$('wrScope').onchange=count;
 $('wrStart').onclick=start;$('wrSubmit').onclick=submit;$('wrNext').onclick=next;
 $('wrClear').onclick=()=>{save({wrong:[]});count();};$('wrClose').onclick=()=>m.close('written');
 win.opener=count;chapters();
}
root.SimWritten={init,start,pool,wrongIds};
})(window);
